<?php get_header(); $term=get_queried_object(); $cover=absint(get_term_meta($term->term_id,'gmr_collection_cover_id',true)); ?>
<section class="gmr-term-hero"><div class="gmr-term-hero__image"><?php echo wp_get_attachment_image($cover,'full'); ?></div><div class="gmr-term-hero__content"><span class="gmr-kicker">Coleccion</span><h1><?php echo esc_html($term->name);?></h1><p><?php echo esc_html(get_term_meta($term->term_id,'gmr_collection_subtitle',true));?></p></div></section>
<?php $text=get_term_meta($term->term_id,'gmr_collection_text',true);if($text):?><section class="gmr-section"><div class="gmr-wrap gmr-editorial"><?php echo wp_kses_post(wpautop($text));?></div></section><?php endif;?><section class="gmr-section gmr-section--white"><div class="gmr-wrap"><?php if(have_posts()){echo '<div class="gmr-grid">';while(have_posts()){the_post();get_template_part('template-parts/artwork','card');}echo '</div>';the_posts_pagination();}else echo '<p class="gmr-empty">No hay obras visibles en esta coleccion.</p>';?></div></section><?php get_footer(); ?>
